from taf.fdsw.rc.interfaces.FDSW21D.fdsw import FDSW21D


class FDSW21F(FDSW21D):
    VERSION_NAME = 'FDSW21F'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW21F, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
